1	import { useEffect, useRef, useState, type FormEvent } from "react";
2	import { useMutation } from "convex/react";
3	import { ConvexError } from "convex/values";
4	import { api } from "../convex/_generated/api";
5	import { isValidEmail } from "./lib";
6	
7	// The public /#/join waitlist. One page that becomes two: a wide viewport gets
8	// the "constellation" layout (copy settled in the lower third), a narrow one
9	// gets the "drift" layout (headline up top, capture at the bottom). Both ride
10	// the same drifting star field. The 620px breakpoint drives layout and copy
11	// together so they never disagree.
12	type Mode = "desktop" | "phone";
13	type Status = "idle" | "submitting" | "joined";
14	
15	const BREAKPOINT = 620;
16	
17	function initialMode(): Mode {
18	  return typeof window !== "undefined" && window.innerWidth >= BREAKPOINT
19	    ? "desktop"
20	    : "phone";
21	}
22	
23	// Copy shifts with the layout; each side keeps the wording it was designed with.
24	const COPY: Record<Mode, {
25	  headline: string;
26	  sub: string;
27	  cta: string;
28	  fine: string;
29	}> = {
30	  desktop: {
31	    headline: "Your people are a constellation.",
32	    sub: "Every person you meet becomes a point of light - and Euno keeps them from drifting away.",
33	    cta: "Join",
34	    fine: "Private beta",
35	  },
36	  phone: {
37	    headline: "The people you meet, never lost again.",
38	    sub: "A quiet memory layer over the people of your life. Get in early.",
39	    cta: "Request access",
40	    fine: "No spam. Invites go out in waves.",
41	  },
42	};
43	
44	function CheckIcon() {
45	  return (
46	    <svg viewBox="0 0 24 24" fill="none" stroke="#0a84ff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
47	      <path d="M20 6 9 17l-5-5" />
48	    </svg>
49	  );
50	}
51	
52	export function Waitlist() {
53	  const rootRef = useRef<HTMLDivElement | null>(null);
54	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
55	  const [mode, setMode] = useState<Mode>(initialMode);
56	  const [name, setName] = useState("");
57	  const [email, setEmail] = useState("");
58	  const [status, setStatus] = useState<Status>("idle");
59	  const [error, setError] = useState<string | null>(null);
60	  const join = useMutation(api.waitlist.joinWaitlist);
61	
62	  // Layout follows the page width, flipping at the same breakpoint the copy
63	  // uses so the two stay in step.
64	  useEffect(() => {
65	    const root = rootRef.current;
66	    if (root === null) return;
67	    const observer = new ResizeObserver(([entry]) => {
68	      setMode(entry.contentRect.width >= BREAKPOINT ? "desktop" : "phone");
69	    });
70	    observer.observe(root);
71	    return () => observer.disconnect();
72	  }, []);
73	
74	  // The drifting star field. Lives for the component's lifetime and tears
75	  // down its animation frame on unmount; a still frame under reduced motion.
76	  useEffect(() => {
77	    const canvas = canvasRef.current;
78	    if (canvas === null) return;
79	    return startDrift(canvas);
80	  }, []);
81	
82	  async function onSubmit(event: FormEvent) {
83	    event.preventDefault();
84	    setError(null);
85	    // Checked in field order (name above email) so the first error shown is
86	    // the first thing the person needs to fix.
87	    if (name.trim() === "") {
88	      setError("Enter your name.");
89	      return;
90	    }
91	    if (!isValidEmail(email)) {
92	      setError("Enter a valid email address.");
93	      return;
94	    }
95	    setStatus("submitting");
96	    try {
97	      await join({ name: name.trim(), email, source: mode });
98	      setStatus("joined");
99	    } catch (err) {
100	      setStatus("idle");
101	      // ConvexError carries our own server message; anything else is a network
102	      // or unexpected failure the person can just retry.
103	      setError(
104	        err instanceof ConvexError && typeof err.data === "string"
105	          ? err.data
106	          : "Something went wrong. Please try again.",
107	      );
108	    }
109	  }
110	
111	  const copy = COPY[mode];
112	
113	  return (
114	    <div ref={rootRef} className="waitlist" data-mode={mode}>
115	      <canvas ref={canvasRef} className="wl-sky" aria-hidden="true" />
116	      <div className="wl-content">
117	        {status === "joined" ? (
118	          <div className="wl-joined" role="status">
119	            <div className="wl-check" aria-hidden="true">
120	              <CheckIcon />
121	            </div>
122	            <p className="wl-checkline">You are on the list.</p>
123	            <p className="wl-sub wl-joined-sub">
124	              Thank you for joining us, to be in the true social that brings you to other people in your life
125	            </p>
126	          </div>
127	        ) : (
128	          <>
129	            <div className="wl-top">
130	              <span className="wl-eyebrow">Euno - private beta</span>
131	              <h1 className="wl-headline">{copy.headline}</h1>
132	            </div>
133	            <div className="wl-bottom">
134	              <p className="wl-sub">{copy.sub}</p>
135	              <form className="wl-form" onSubmit={onSubmit} noValidate>
136	                <input
137	                  className="wl-field"
