            <div className="wl-check" aria-hidden="true">
              <CheckIcon />
            </div>
            <p className="wl-checkline">You are on the list.</p>
            <p className="wl-sub wl-joined-sub">
              Thank you for joining us, to be in the true social that brings you to other people in your life
            </p>
          </div>
        ) : (
          <>
            <div className="wl-top">
              <span className="wl-eyebrow">Euno - private beta</span>
              <h1 className="wl-headline">{copy.headline}</h1>
            </div>
            <div className="wl-bottom">
              <p className="wl-sub">{copy.sub}</p>
              <form
                className={revealed ? "wl-form is-revealed" : "wl-form"}
                onSubmit={onSubmit}
                noValidate
              >
                <div className="wl-name-row">
                  <input
                    className="wl-field"
                    type="text"
                    autoComplete="name"
                    placeholder="Your name"
                    aria-label="Your name"
                    value={name}
                    onFocus={() => setRevealed(true)}
                    onChange={(event) => {
                      setName(event.target.value);
                      setRevealed(true);
                      if (error !== null) setError(null);
                    }}
                  />
                  {/* Join rides alongside the name until the email drops in,
                      then hands off to the email row's button. */}
                  <button
                    className="wl-go wl-go-name"
                    type="submit"
                    disabled={status === "submitting"}
                    inert={revealed}
                  >
                    {status === "submitting" ? "Joining" : copy.cta}
                  </button>
                </div>
                <div className="wl-email-wrap" inert={!revealed}>
                  <div className="wl-email-row">
                    <input
                      className="wl-field"
                      type="email"
                      inputMode="email"
                      autoComplete="email"
                      placeholder="Your email"
                      aria-label="Email address"
                      value={email}
                      onChange={(event) => {
                        setEmail(event.target.value);
                        if (error !== null) setError(null);
                      }}
                    />
                    <button className="wl-go" type="submit" disabled={status === "submitting"}>
                      {status === "submitting" ? "Joining" : copy.cta}
                    </button>
                  </div>
                </div>
              </form>
              {error !== null ? (
                <p className="wl-error" role="alert">{error}</p>
              ) : (
                <p className="wl-fine">{copy.fine}</p>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

type Star = {
  x: number;
  y: number;
  size: number;
  base: number;
  sp: number;
  tw: number;
  hot: boolean;
};

// A layered parallax field drifting rightward -- deeper (bigger, brighter)
// stars move faster. Returns its own teardown. Ported from the approved
// prototype so the shipped page matches it exactly.
function startDrift(canvas: HTMLCanvasElement): () => void {
  const ctx = canvas.getContext("2d");
  if (ctx === null) return () => {};
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  let w = 0;
  let h = 0;
  let raf = 0;
  let stars: Star[] = [];

  function size() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = canvas.clientWidth;
    h = canvas.clientHeight;
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function build() {
    size();
    const count = Math.min(300, Math.floor((w * h) / 3600));
    stars = [];
    for (let i = 0; i < count; i++) {
      const depth = Math.random();
      stars.push({
        x: Math.random() * w,
        y: Math.random() * h,
        size: 0.5 + depth * 1.6,
        base: 0.1 + depth * 0.45,
        sp: 0.05 + depth * 0.22,
        tw: Math.random() * 6.28,
        hot: Math.random() < 0.04,
      });
    }
  }

  function frame(t: number) {
    const time = t / 1000;
    ctx!.clearRect(0, 0, w, h);
    for (const s of stars) {
      if (!reduce) {
        s.x += s.sp;
        if (s.x > w + 2) s.x = -2;
      }
      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
      ctx!.beginPath();
      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
      if (s.hot) {
        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
        ctx!.shadowColor = "rgba(10,132,255,.8)";
        ctx!.shadowBlur = 6;
      } else {
        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
        ctx!.shadowBlur = 0;
      }
      ctx!.fill();
    }
    ctx!.shadowBlur = 0;
    if (!reduce) raf = requestAnimationFrame(frame);
  }

  function onResize() {
    build();
    if (reduce) frame(0);
  }

  build();
  if (reduce) frame(0);
  else raf = requestAnimationFrame(frame);
  window.addEventListener("resize", onResize);

  return () => {
    cancelAnimationFrame(raf);
    window.removeEventListener("resize", onResize);
  };
}

import { useEffect, useState, type FormEvent } from "react";
import { useMutation, useQuery } from "convex/react";
import type { FunctionReturnType } from "convex/server";
import { api } from "../convex/_generated/api";

type NearbyResult = FunctionReturnType<typeof api.loveAlarm.nearby>;

const HEARTBEAT_MS = 25_000;

function defaultRoomCode(): string {
  return new Date().toISOString().slice(0, 10).replace(/-/g, "");
}

export function LoveAlarmPanel() {
  const startPresence = useMutation(api.loveAlarm.startPresence);
  const heartbeat = useMutation(api.loveAlarm.heartbeat);
  const stopPresence = useMutation(api.loveAlarm.stopPresence);
  const [open, setOpen] = useState(false);
  const [roomCode, setRoomCode] = useState(defaultRoomCode);
  const [displayName, setDisplayName] = useState("");
  const [joinedRoom, setJoinedRoom] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const nearby = useQuery(
    api.loveAlarm.nearby,
    joinedRoom === null ? "skip" : { roomCode: joinedRoom },
  );

  useEffect(() => {
    if (joinedRoom === null) return;
    const timer = window.setInterval(() => {
      heartbeat({ roomCode: joinedRoom }).catch(() => {
        setJoinedRoom(null);
        setError("Radar paused. Join the room again when you are ready.");
      });
    }, HEARTBEAT_MS);
    return () => window.clearInterval(timer);
  }, [heartbeat, joinedRoom]);

  async function handleJoin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saving) return;
    setSaving(true);
    setError(null);
    try {
      const started = await startPresence({
        roomCode,
        displayName: displayName === "" ? undefined : displayName,
      });
      setJoinedRoom(started.roomCode);
      setRoomCode(started.roomCode);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not start radar");
    } finally {
      setSaving(false);
    }
  }

  async function handleStop() {
    if (joinedRoom === null) return;
    const room = joinedRoom;
    setJoinedRoom(null);
    setError(null);
    await stopPresence({ roomCode: room }).catch(() => {
      setError("Could not stop radar. It will expire shortly.");
    });
  }

  const peers: NearbyResult["peers"] = nearby?.peers ?? [];

  if (!open) {
    return (
      <div className="love-alarm">
        <button
          className="love-alarm-toggle"
          type="button"
          onClick={() => setOpen(true)}
        >
          Love Alarm
        </button>
      </div>
    );
  }

  return (
    <section className="love-alarm love-alarm-card" aria-labelledby="love-alarm-title">
      <div className="love-alarm-head">
        <div>
          <p className="sky-label">opt-in radar</p>
          <h2 id="love-alarm-title">Love Alarm</h2>
        </div>
        <button
          className="love-alarm-close"
          type="button"
          aria-label="Close Love Alarm"
          onClick={() => setOpen(false)}
        >
          Close
        </button>
      </div>

      {joinedRoom === null ? (
        <form className="love-alarm-form" onSubmit={handleJoin}>
          <p className="love-alarm-copy">
            Share a small code with someone nearby. Euno listens only while this room
            is open.
          </p>
          <label>
            <span>Room code</span>
            <input
              className="love-alarm-input"
              value={roomCode}
              onChange={(event) => setRoomCode(event.target.value)}
              autoCapitalize="characters"
              autoComplete="off"
            />
          </label>
          <label>
            <span>Display name</span>
            <input
              className="love-alarm-input"
              value={displayName}
              onChange={(event) => setDisplayName(event.target.value)}
              placeholder="Someone nearby"
              autoComplete="off"
            />
          </label>
          {error !== null && <p className="love-alarm-error">{error}</p>}
          <button className="love-alarm-primary" type="submit" disabled={saving}>
            {saving ? "Starting" : "Start radar"}
          </button>
        </form>
      ) : (
        <div className="love-alarm-active">
          <p className="love-alarm-copy">
            Room <strong>{joinedRoom}</strong> is open for the next few minutes.
          </p>
          {nearby === undefined ? (
            <p className="love-alarm-muted">Listening quietly...</p>
          ) : peers.length === 0 ? (
            <p className="love-alarm-muted">No one else has joined this room yet.</p>
          ) : (
            <ul className="love-alarm-peers" aria-label="Nearby people">
              {peers.map((peer) => (
                <li key={`${peer.displayName}-${peer.lastSeenAt}`}>
                  <span className="love-alarm-dot" aria-hidden="true" />
                  {peer.displayName}
                </li>
              ))}
            </ul>
          )}
          {error !== null && <p className="love-alarm-error">{error}</p>}
          <button className="love-alarm-secondary" type="button" onClick={handleStop}>
            Stop radar
          </button>
        </div>
      )}
    </section>
  );
}

